import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"7、【師】 坎下坤上","description":"橫渠易說 - 7、【師】 坎下坤上","frontmatter":{"title":"7、【師】 坎下坤上","description":"橫渠易說 - 7、【師】 坎下坤上"},"headers":[],"relativePath":"classics/hengqu/009.md","filePath":"classics/hengqu/009.md"}'),l={name:"classics/hengqu/009.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_7、【師】-坎下坤上" tabindex="-1">7、【師】 坎下坤上 <a class="header-anchor" href="#_7、【師】-坎下坤上" aria-label="Permalink to “7、【師】 坎下坤上”">​</a></h1><p>丈人剛過，太公近之。剛正、剛中，則是大人聖人，得中道也。太公則必待誅紂時，雖鷹揚，所以為剛過，不得稱大人。</p><h3 id="彖曰-師-眾也-貞-正也-能以眾正-可以王矣。剛中而應-行險而順-以此毒天下而民從之-吉又何咎矣" tabindex="-1">彖曰：師，眾也；貞，正也；能以眾正，可以王矣。剛中而應，行險而順，以此毒天下而民從之，吉又何咎矣! <a class="header-anchor" href="#彖曰-師-眾也-貞-正也-能以眾正-可以王矣。剛中而應-行險而順-以此毒天下而民從之-吉又何咎矣" aria-label="Permalink to “彖曰：師，眾也；貞，正也；能以眾正，可以王矣。剛中而應，行險而順，以此毒天下而民從之，吉又何咎矣!”">​</a></h3><h3 id="象曰-地中有水-師-君子以容民畜眾。" tabindex="-1">象曰：地中有水，師，君子以容民畜眾。 <a class="header-anchor" href="#象曰-地中有水-師-君子以容民畜眾。" aria-label="Permalink to “象曰：地中有水，師，君子以容民畜眾。”">​</a></h3><h3 id="初六-師出以律-否臧兇。-象曰-師出以律-失律兇也。" tabindex="-1">初六，師出以律，否臧兇。 象曰：“師出以律”，失律兇也。 <a class="header-anchor" href="#初六-師出以律-否臧兇。-象曰-師出以律-失律兇也。" aria-label="Permalink to “初六，師出以律，否臧兇。 象曰：“師出以律”，失律兇也。”">​</a></h3><p>師出以律”，師之始也，體柔居賤，不善用律，故兇。</p><h3 id="九二-在師中-吉-無咎。王三錫命。-象曰-在師中吉-承天寵也。-王三錫命-懷萬邦也。" tabindex="-1">九二，在師中，吉，無咎。王三錫命。 象曰：“在師中吉”，承天寵也。“王三錫命”，懷萬邦也。 <a class="header-anchor" href="#九二-在師中-吉-無咎。王三錫命。-象曰-在師中吉-承天寵也。-王三錫命-懷萬邦也。" aria-label="Permalink to “九二，在師中，吉，無咎。王三錫命。 象曰：“在師中吉”，承天寵也。“王三錫命”，懷萬邦也。”">​</a></h3><p>懷愛萬邦，故所以重將帥。</p><h3 id="六三-師或輿尸-兇。-象曰-師或輿尸-大無功也。" tabindex="-1">六三，師或輿尸，兇。 象曰：“師或輿尸”，大無功也。 <a class="header-anchor" href="#六三-師或輿尸-兇。-象曰-師或輿尸-大無功也。" aria-label="Permalink to “六三，師或輿尸，兇。 象曰：“師或輿尸”，大無功也。”">​</a></h3><p>陰柔之質，履不以正，以此帥眾，固不能一。師丈人吉，非陰柔所御。</p><h3 id="六四-師左次-無咎。-象曰-左次無咎-未失常也。" tabindex="-1">六四，師左次，無咎。 象曰：“左次無咎”，未失常也。 <a class="header-anchor" href="#六四-師左次-無咎。-象曰-左次無咎-未失常也。" aria-label="Permalink to “六四，師左次，無咎。 象曰：“左次無咎”，未失常也。”">​</a></h3><p>次之不戰之地，則不失其常。</p><h3 id="六五-田有禽-利執言-無咎。長子帥師-弟子輿尸-貞兇。-象曰-長子帥師-以中行也-弟子輿尸-使不當也。" tabindex="-1">六五，田有禽，利執言，無咎。長子帥師，弟子輿尸，貞兇。 象曰：“長子帥師”，以中行也；“弟子輿尸”，使不當也。 <a class="header-anchor" href="#六五-田有禽-利執言-無咎。長子帥師-弟子輿尸-貞兇。-象曰-長子帥師-以中行也-弟子輿尸-使不當也。" aria-label="Permalink to “六五，田有禽，利執言，無咎。長子帥師，弟子輿尸，貞兇。 象曰：“長子帥師”，以中行也；“弟子輿尸”，使不當也。”">​</a></h3><p>柔居盛位，見犯乃較，故無咎。任寄非一，行師之兇也。</p><h3 id="上六-大君有命-開國承家-小人勿用。-象曰-大君有命-以正功也。-小人勿用-必亂邦也。" tabindex="-1">上六，大君有命，開國承家，小人勿用。 象曰：“大君有命”，以正功也。“小人勿用”，必亂邦也。 <a class="header-anchor" href="#上六-大君有命-開國承家-小人勿用。-象曰-大君有命-以正功也。-小人勿用-必亂邦也。" aria-label="Permalink to “上六，大君有命，開國承家，小人勿用。 象曰：“大君有命”，以正功也。“小人勿用”，必亂邦也。”">​</a></h3><p>師終必推賞，然小人雖有功，不可胙之以上，長亂也。承，猶繼世之承也。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
